toad_implementation.code_blueprint:
canvas {
  size: 800px 1050px;
  fill: #0A0A0A;
  font-family: "Oswald, sans-serif";
}

>soot = #0A0A0A;
>karmin = #D90429;
>chalk = #EDF2F4;

circle #surrealEyeOuter {
  at: center of canvas offset 0px -140px;
  size: 340px;
  fill: >chalk;
  stroke: >karmin;
  stroke-width: 6px;
}

circle #surrealPupil {
  at: center of #surrealEyeOuter;
  size: 160px;
  fill: >karmin;
}

circle #innerVoid {
  at: center of #surrealPupil;
  size: 60px;
  fill: >soot;
}

text #posterTitle {
  at: below #surrealEyeOuter offset 80px;
  content: "K A F K A";
  font-size: 88px;
  font-weight: 900;
  color: >karmin;
}

text #posterSubtitle {
  at: below #posterTitle offset 10px;
  content: "DIE VERWANDLUNG // THEATER FESTIVAL";
  font-size: 20px;
  font-weight: 700;
  color: >chalk;
}

text #datesFooter {
  at: bottom center of canvas offset 0px -48px;
  content: "TEATR NOWY • WARSZAWA • PAŹDZIERNIK 2026";
  font-size: 13px;
  color: #888888;
}
